//! Generated from the IANA tz database - do not edit by hand.
//! (tools/gen_tzdata.py, from tzdata.zi + the compiled TZif footers.)
//!
//! Every zone name the database knows, primary names and links alike, with
//! its standard UTC offset and, when it observes DST, the recurring rule from
//! the zone's POSIX TZ footer. `canon` indexes the name that stands for the
//! whole link group, which is what time-zone equality compares. The rules are
//! the zones' *present-day* ones: historical transitions are not modelled.

/// A recurring DST rule: `week` 1-4 selects the Nth `dow` of the month, 5 the
/// last; `sec` is the transition's local time as seconds past midnight.
pub const Rule = struct {
    start_month: u8,
    start_week: u8,
    start_dow: u8,
    start_sec: i32,
    end_month: u8,
    end_week: u8,
    end_dow: u8,
    end_sec: i32,
};

pub const Zone = struct {
    name: []const u8,
    canon: u16,
    std_offset_sec: i32,
    dst_save_sec: i32 = 0,
    rule: ?Rule = null,
};

